namespace Payments;

public sealed class SettlementBatchProcessor
{
    public SettlementResult Process(string merchantId, IEnumerable<PaymentItem> items, string settlementCurrency,
        decimal percentageFee, decimal fixedFee, decimal submissionLimit, ISettlementGateway gateway)
    {
        var lines = new List<SettlementLine>();
        var accepted = new List<(string Reference, decimal Net)>();
        var seen = new HashSet<string>(StringComparer.Ordinal);
        var total = 0m;

        foreach (var item in items)
        {
            if (!TryAccept(item, settlementCurrency, percentageFee, fixedFee, submissionLimit,
                    total, seen, out var net, out var rejectionStatus))
            {
                lines.Add(new SettlementLine(item.Reference, 0m, rejectionStatus));
                continue;
            }

            accepted.Add((item.Reference, net));
            total += net;
        }

        if (accepted.Count == 0)
            return new SettlementResult(lines, 0m, "empty");

        if (string.IsNullOrWhiteSpace(merchantId))
            return CreateRejectedResult(lines, accepted, "invalid-merchant");

        var gatewayResult = gateway.Submit(
            merchantId,
            settlementCurrency,
            total,
            accepted.Select(entry => entry.Reference).ToArray());

        if (!gatewayResult.Accepted)
            return CreateRejectedResult(lines, accepted, $"gateway-{gatewayResult.Code}");

        lines.AddRange(accepted.Select(entry => new SettlementLine(entry.Reference, entry.Net, "submitted")));
        var status = lines.Any(line => line.Status != "submitted") ? "partial" : "submitted";
        return new SettlementResult(lines, total, status);
    }

    private static bool TryAccept(PaymentItem item, string settlementCurrency, decimal percentageFee,
        decimal fixedFee, decimal submissionLimit, decimal acceptedTotal, HashSet<string> seen,
        out decimal net, out string rejectionStatus)
    {
        net = 0m;

        rejectionStatus = ValidateItem(item, settlementCurrency, seen);
        if (rejectionStatus.Length != 0)
            return false;

        var fee = decimal.Round(item.GrossAmount * percentageFee + fixedFee, 2);
        net = decimal.Round(item.GrossAmount - fee, 2);
        if (net <= 0m)
        {
            rejectionStatus = "fee-exceeds-amount";
            return false;
        }

        if (acceptedTotal + net > submissionLimit)
        {
            rejectionStatus = "batch-limit";
            return false;
        }

        rejectionStatus = string.Empty;
        return true;
    }

    private static string ValidateItem(PaymentItem item, string settlementCurrency, HashSet<string> seen)
    {
        if (string.IsNullOrWhiteSpace(item.Reference))
            return "invalid-reference";
        if (!seen.Add(item.Reference))
            return "duplicate";
        if (!string.Equals(item.Currency, settlementCurrency, StringComparison.OrdinalIgnoreCase))
            return "currency-mismatch";
        if (item.GrossAmount <= 0m)
            return "invalid-amount";
        if (item.Refunded)
            return "refunded";
        if (item.Held)
            return "held";

        return string.Empty;
    }

    private static SettlementResult CreateRejectedResult(List<SettlementLine> lines,
        List<(string Reference, decimal Net)> accepted, string rejectionStatus)
    {
        return new SettlementResult(
            [.. lines, .. accepted.Select(entry => new SettlementLine(entry.Reference, 0m, rejectionStatus))],
            0m,
            "rejected");
    }
}
